query:
from logs-*, filebeat-*, winlogbeat-*, packetbeat-* metadata _id, _index, _version | where ends_with(azure.activitylogs.operation_name, "/deployments/validate/action")
| eval timebucket=date_trunc(1minutes, @timestamp) | stats event_count=count() by timebucket, azure.activitylogs.identity.claims_initiated_by_user.name
| where event_count >= 5

from logs-*, filebeat-*, winlogbeat-*, packetbeat-* metadata _id, _index, _version | where azure.signinlogs.properties.status.error_code in (50126, 50053, 50055, 50056)
| eval timebucket=date_trunc(30minutes, @timestamp) | stats value_count=count_distinct(azure.signinlogs.properties.user_principal_name) by timebucket, source.ip
| where value_count >= 20

from logs-*, filebeat-*, winlogbeat-*, packetbeat-* metadata _id, _index, _version | where aws.cloudtrail.error_code in ("AccessDenied", "AccessDeniedException", "UnauthorizedOperation", "Client.UnauthorizedOperation")
| eval timebucket=date_trunc(10minutes, @timestamp) | stats value_count=count_distinct(event.action) by timebucket, aws.cloudtrail.user_identity.arn
| where value_count >= 15

any where
  // EQL's : operator ignores case, so ScopeWeaver/1.0 and ARTEX-PENTEST/1.0 match. KQL wildcards on a keyword field do not.
  user_agent.original : ("*artex-readonly/*", "*artex-pentest/*", "*artex-audit/*", "*artex-verify/*", "*artex-spawn/*", "*artex-worker/*",
                         "*artex-enrich/*", "*artex-i21861-canary*", "*artex-agent*", "*artex-judge-*", "*mozilla/5.0 (artex)*", "*artexverify/*", "*artex/1.0*", "*scopeweaver*", "*spa-api-recon*") or
  // ARTeX is an indicator only in this exact mixed case, so it uses like, which is case-sensitive.
  user_agent.original like "*ARTeX*"
